 public class TimelinePoint {public DateTime Time;public double? Cpu,Ram,Gpu,Disk;}
 public sealed class Timeline:FrameworkElement {
  readonly List<TimelinePoint> points=new List<TimelinePoint>();
  Color[] colors={Color.FromRgb(88,224,187),Color.FromRgb(116,171,255),Color.FromRgb(251,199,119),Color.FromRgb(189,155,255)};
  Color gridColor=Color.FromRgb(38,53,72),labelColor=Color.FromRgb(142,164,186);
  public void ApplyTheme(bool light){colors=light?new[]{Color.FromRgb(8,122,96),Color.FromRgb(40,100,180),Color.FromRgb(150,96,14),Color.FromRgb(123,75,188)}:new[]{Color.FromRgb(88,224,187),Color.FromRgb(116,171,255),Color.FromRgb(251,199,119),Color.FromRgb(189,155,255)};gridColor=light?Color.FromRgb(223,230,239):Color.FromRgb(38,53,72);labelColor=light?Color.FromRgb(82,101,121):Color.FromRgb(142,164,186);InvalidateVisual();}
  public void Add(Snapshot x){DateTime stamp;if(!DateTime.TryParse(x.timestamp_utc,null,System.Globalization.DateTimeStyles.RoundtripKind,out stamp))return;stamp=stamp.ToLocalTime();if(points.Count>0&&stamp<=points[points.Count-1].Time)return;
   points.Add(new TimelinePoint{Time=stamp,Cpu=x.cpu_percent,Ram=x.memory_percent,Gpu=x.gpu!=null&&x.gpu.status=="ok"?x.gpu.utilization_percent:null,Disk=x.disk_active_percent});while(points.Count>180)points.RemoveAt(0);InvalidateVisual();}
  protected override void OnRender(DrawingContext dc){base.OnRender(dc);double w=Math.Max(20,ActualWidth-48),h=Math.Max(20,ActualHeight-44),left=30,top=8;
   for(int i=0;i<=4;i++){double y=top+h-h*i/4;dc.DrawLine(new Pen(new SolidColorBrush(gridColor),1),new Point(left,y),new Point(left+w,y));Text(dc,(i*25).ToString(),1,y-7,10);}
   if(points.Count<2){Text(dc,"Aguardando as primeiras amostras…",left+12,top+h/2,12);return;}
   double span=Math.Max(.001,(points.Last().Time-points[0].Time).TotalSeconds);
   for(int series=0;series<4;series++){Point? old=null;var pen=new Pen(new SolidColorBrush(colors[series]),2);for(int i=0;i<points.Count;i++){var p=points[i];double? v=series==0?p.Cpu:series==1?p.Ram:series==2?p.Gpu:p.Disk;if(!v.HasValue){old=null;continue;}if(i>0&&(p.Time-points[i-1].Time).TotalSeconds>10)old=null;var pos=new Point(left+w*(p.Time-points[0].Time).TotalSeconds/span,top+h-h*Util.Clamp(v.Value)/100);if(old.HasValue)dc.DrawLine(pen,old.Value,pos);old=pos;}}
   Text(dc,points[0].Time.ToString("HH:mm:ss"),left,top+h+12,10);Text(dc,points.Last().Time.ToString("HH:mm:ss"),left+w-53,top+h+12,10);
  }
  void Text(DrawingContext dc,string value,double x,double y,double size){var text=new FormattedText(value,System.Globalization.CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),size,new SolidColorBrush(labelColor),1.0);dc.DrawText(text,new Point(x,y));}
 }
