  async void Mark(object sender,RoutedEventArgs e){ShowPanel();TextBox box;var dialog=CreateMarkerDialog(out box);try{if(await dialog.ShowAsync()==ContentDialogResult.Primary){engine.Mark("user_marker","info","Travamento marcado pelo usuário",new{note=Util.Clean(box.Text),user_reported=true});}}catch(Exception ex){MessageBox.Show(this,Util.Clean(ex.Message),"PC Monitor");}}
