  public void ShowPanel(){if(!Dispatcher.CheckAccess()){Dispatcher.BeginInvoke(new Action(ShowPanel));return;}ShowInTaskbar=true;ShowActivated=true;WindowState=WindowState.Normal;Show();Activate();if(engine.Latest!=null)Render(engine.Latest);}
  void HandleClosing(object sender,CancelEventArgs e){if(!quitting){e.Cancel=true;Hide();}}
  public void Exit(){if(!Dispatcher.CheckAccess()){Dispatcher.BeginInvoke(new Action(Exit));return;}quitting=true;engine.Mark("monitor_stopped","info","Monitor encerrado pelo usuário",null);Close();Cleanup();Application.Current.Shutdown();}
  void Power(object s,Microsoft.Win32.PowerModeChangedEventArgs e){engine.Mark("power_"+e.Mode.ToString().ToLowerInvariant(),"info","Energia: "+e.Mode,null);}
  void Ending(object s,Microsoft.Win32.SessionEndingEventArgs e){engine.Mark("session_ending","info","Sessão do Windows encerrando",null);Dispatcher.BeginInvoke(new Action(Exit));}
  void Cleanup(){if(closed)return;closed=true;timer.Stop();bridge.Dispose();engine.Sampled-=Sample;engine.IncidentRaised-=Incident;engine.WindowsEvent-=WindowsEvent;Microsoft.Win32.SystemEvents.PowerModeChanged-=Power;Microsoft.Win32.SystemEvents.SessionEnding-=Ending;tray.Visible=false;tray.Dispose();engine.Dispose();}
